mapper.update:
update fangzhi set dizhi =#{dizhi},mianji=#{mianji},jiage=#{jiage},zhuangtai=#{zhuangtai},
    jiaju=#{jiaju,jdbcType=VARCHAR},shuidian=#{shuidian,jdbcType=VARCHAR},zuqi=#{zuqi,jdbcType=VARCHAR},
    zhuangxiu=#{zhuangxiu,jdbcType=VARCHAR},chanquan=#{chanquan,jdbcType=VARCHAR},wuye=#{wuye,jdbcType=VARCHAR}
where hid = #{hid} and deleted = 0;
